import java.util.*

fun main(args: Array<String>) {
    val sc = Scanner(System.`in`)
    val l = sc.nextLong()
    val r = sc.nextLong()

    var maxProd = 0L

    // Check all numbers in the range [l, r]
    // However, for large ranges, we need a smarter approach
    // The maximum product occurs when n and ψ(n) are as close as possible to each other
    // The optimal n is around 499...999 (half of 999...999)
    // So we check candidates around the midpoint of the range and the optimal candidate

    // Generate candidates:
    // 1. The optimal candidate (499...999)
    // 2. The midpoint of l and r
    // 3. l and r themselves
    // 4. Numbers around the midpoint

    val candidates = mutableSetOf<Long>()

    // Add l and r
    candidates.add(l)
    candidates.add(r)

    // Add midpoint
    val mid = (l + r) / 2
    candidates.add(mid)

    // Add numbers around midpoint
    for (i in -5..5) {
        val candidate = mid + i
        if (candidate >= l && candidate <= r) {
            candidates.add(candidate)
        }
    }

    // Generate the optimal candidate (499...999)
    val rStr = r.toString()
    val len = rStr.length
    val optimalBuilder = StringBuilder()
    optimalBuilder.append('4')
    for (i in 1 until len) {
        optimalBuilder.append('9')
    }
    val optimal = optimalBuilder.toString().toLong()
    if (optimal >= l && optimal <= r) {
        candidates.add(optimal)
    }

    // Also check optimal - 1 and optimal + 1
    candidates.add(optimal - 1)
    candidates.add(optimal + 1)

    // Check all candidates
    for (n in candidates) {
        if (n < l || n > r) continue
        val psiN = reflect(n)
        val prod = n * psiN
        if (prod > maxProd) {
            maxProd = prod
        }
    }

    println(maxProd)
}

fun reflect(n: Long): Long {
    val s = n.toString()
    val reflected = StringBuilder()
    for (c in s) {
        val digit = c - '0'
        reflected.append((9 - digit) + '0')
    }
    // Remove leading zeros
    var result = reflected.toString().toLong()
    return result
}
